    AND recommendation_type = #{recommendationType}


    AND status = #{status}


    AND benefit_level = #{benefitLevel}


    AND risk_level = #{riskLevel}


    AND validation_status = #{validationStatus}


    AND requires_dispatch = #{requiresDispatch}


    AND manual_review_required = #{manualReviewRequired}


    AND source_type = #{sourceType}



        AND source_kind IN

            #{sourceKindItem}




            AND source_kind = #{sourceKind}




    AND source_id = #{sourceId}


    AND history_id = #{historyId}


    AND parse_task_id = #{parseTaskId}


    AND batch_id = #{batchId}


    AND report_code = #{reportCode}

